Path('frontend/react/src/features/dashboard/DashboardPage.tsx').write_text('''import React, { useEffect, useState } from "react";\nimport { Square, Zap, Wifi } from "lucide-react";\nimport { api, send } from "../../services/api";\nimport type { InternetHealth, Status, User } from "../../types";\nimport { Header, PanelTitle, Empty, Metric, Legend, canEdit, hasPermission } from "../../components/Common";\n\ntype Resources = { current: { cpu_percent:number; process_cpu_percent:number; ram_percent:number; process_rss_bytes:number; disk_percent:number; disk_free_bytes:number; process_threads:number }; history: Array<{timestamp:string;cpu_percent:number;ram_percent:number}> };\nconst mb=(n:number)=>`${(n/1024/1024).toFixed(1)} MB`; const gb=(n:number)=>`${(n/1024/1024/1024).toFixed(1)} GB`;\nfunction Sparkline({values}:{values:number[]}) { const w=420,h=90,max=Math.max(...values,1),min=Math.min(...values,0); const points=values.map((v,i)=>`${(i/Math.max(values.length-1,1))*w},${h-((v-min)/Math.max(max-min,1))*h`).join(" "); return <svg className="metric-chart" viewBox={`0 0 ${w} ${h}`} role="img"><polyline fill="none" points={points}/></svg>; }\n\nexport function Dashboard({ user }: { user: User }) {\n    const [data,setData]=useState<Status|null>(null), [internet,setInternet]=useState<InternetHealth|null>(null), [resources,setResources]=useState<Resources|null>(null), [publication,setPublication]=useState("NONE");\n    const canViewLogs=hasPermission(user,"logs","view"), canViewSync=hasPermission(user,"sync","view");\n    const load=()=>api<Status>("/api/status").then(setData).catch(()=>undefined);\n    useEffect(()=>{load();const t=setInterval(load,3000);return()=>clearInterval(t)},[]);\n    useEffect(()=>{const a=()=>api<InternetHealth>("/api/v1/internet-health").then(setInternet).catch(()=>setInternet(null));const b=()=>api<Resources>("/api/v1/resources").then(setResources).catch(()=>setResources(null));a();b();const t=setInterval(()=>{a();b()},3000);return()=>clearInterval(t)},[]);\n    const total=data?.total_canais||0,online=data?.canais_online||0,offline=data?.canais_offline||0,unknown=data?.canais_desconhecidos||Math.max(total-online-offline,0),rate=total&&online+offline?Math.round(online/total*100):null,running=data?.status==="Executando..."||data?.status==="Pausado";\n    const start=()=>send("/api/v1/sync",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({publication_mode:publication})}).then(load).catch(()=>undefined);\n    return <><Header kicker="MONITORAMENTO AO VIVO" title="Painel geral" description="Recursos do servidor, conectividade, canais e execução em tempo real.">{canEdit(user)&&<div className="actions"><select className="button subtle" value={publication} onChange={e=>setPublication(e.target.value)} disabled={running}><option value="NONE">Não publicar links</option><option value="CREATE">Criar links novos</option><option value="UPDATE">Atualizar links existentes</option><option value="CREATE_UPDATE">Criar + atualizar</option></select><button className="button primary" disabled={running} onClick={start}><Zap size={15}/> Iniciar sincronização</button><button className="button subtle" disabled={!running} onClick={()=>send("/api/v1/sync/pause").then(load)}>{data?.status==="Pausado"?"Retomar":"Pausar"}</button><button className="button danger" disabled={!running} onClick={()=>confirm("Interromper a execução atual?")&&send("/api/v1/sync/stop").then(load)}><Square size={14}/> Interromper</button></div>}</Header>\n    <section className="resource-metric-grid"><Metric label="CPU" value={`${resources?.current.cpu_percent??0}%`} detail={`${resources?.current.process_cpu_percent??0}% processo`} tone="blue"/><Metric label="RAM" value={`${resources?.current.ram_percent??0}%`} detail={mb(resources?.current.process_rss_bytes??0)+" processo"} tone="green"/><Metric label="Disco" value={`${resources?.current.disk_percent??0}%`} detail={`${gb(resources?.current.disk_free_bytes??0)} livres`} tone="blue"/><Metric label="Threads" value={resources?.current.process_threads??0} detail="processo atual" tone="blue"/></section>\n    <section className="resource-chart-grid"><div className="panel"><PanelTitle kicker="RECURSOS" title="CPU — histórico" badge="AO VIVO"/><Sparkline values={(resources?.history||[]).map(x=>x.cpu_percent)}/></div><div className="panel"><PanelTitle kicker="RECURSOS" title="RAM — histórico" badge="AO VIVO"/><Sparkline values={(resources?.history||[]).map(x=>x.ram_percent)}/></div></section>\n    <section className="metric-grid"><Metric label="Status do processo" value={data?.status||"Carregando"} detail={canViewLogs?(data?.ultimo_log||"Aguardando dados"):"estado operacional"} tone="blue"/><Metric label="Canais catalogados" value={total} detail="base atual" tone="blue"/><Metric label="Online" value={online} detail={rate===null?"verificando":`${rate}% da base`} tone="green"/><Metric label="Offline / removidos" value={offline} detail="última verificação" tone="red"/></section>\n    <section className="panel internet-status-panel"><PanelTitle kicker="CONECTIVIDADE" title="Internet" badge="TESTE AUTOMÁTICO"/><div className="internet-status-content"><div className={`internet-status ${internet?.online?"online":internet?"offline":"unknown"}`}><i className="internet-status-dot"/><strong>{internet?.online?"ONLINE":internet?"OFFLINE":"VERIFICANDO"}</strong></div><div className="internet-ping"><Wifi size={16}/><span>Ping</span><b>{internet?`${internet.latency_ms} ms`:"—"}</b></div></div></section>\n    <section className="split-grid"><div className="panel health-panel"><PanelTitle kicker="DISTRIBUIÇÃO" title="Saúde dos canais" badge="AO VIVO"/><div className="health-content"><div className="donut" style={{"--progress":`${(rate||0)*3.6}deg`} as React.CSSProperties}><strong>{rate===null?"...":`${rate}%`}</strong><small>{rate===null?"verificando":"online"}</small></div><div className="legend"><Legend label="Online" value={online} color="green"/><Legend label="Offline" value={offline} color="red"/><Legend label="Não verificado" value={unknown} color="muted"/></div></div></div>{canViewLogs&&<div className="panel"><PanelTitle kicker="ATIVIDADE" title="O que está acontecendo" badge={`${data?.log_count||0} eventos`}/><div className="activity-list">{data?.logs?.slice(0,12).map(l=><div className={`activity ${l.level}`} key={`${l.timestamp}-${l.message}`}><time>{l.timestamp.slice(11)}</time><span>{l.message}</span></div>)||<Empty text="Nenhuma atividade registrada."/>}</div></div>}</section>\n    {canViewSync&&<div className="panel"><PanelTitle kicker="PIPELINE" title="Progresso da operação" badge={data?.status||"Ocioso"}/><div className="progress-track"><span style={{width:data?.status==="Concluido"?"100%":running?"62%":"12%"}}/></div><div className="progress-labels"><span>Leitura</span><span>Verificação</span><span>Particionamento</span><span>Concluído</span></div></div>}</>;\n}\n''', encoding='utf-8')

append('frontend/react/src/styles.scss', '''\n.resource-metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.resource-chart-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:18px}.metric-chart{width:100%;height:90px;overflow:visible}.metric-chart polyline{stroke:currentColor;stroke-width:2;opacity:.8}.notification-rail{position:fixed;right:18px;top:18px;width:min(390px,calc(100vw - 36px));z-index:1000;display:flex;flex-direction:column;gap:9px;pointer-events:none}.notification-head,.notification{pointer-events:auto}.notification-head{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border:1px solid var(--border);background:var(--bg-card);border-radius:9px}.notification-head span{display:flex;align-items:center;gap:7px;font-weight:700}.notification{position:relative;display:grid;grid-template-columns:auto 1fr auto;gap:10px;padding:12px;border:1px solid var(--border);background:var(--bg-card);border-radius:10px;box-shadow:0 10px 28px rgba(0,0,0,.14);overflow:hidden}.notification.success{border-left:3px solid #20a464}.notification.warning{border-left:3px solid #d99b20}.notification.error{border-left:3px solid #d94b4b}.notification.info{border-left:3px solid #4788d9}.notification p{margin:3px 0;font-size:12px}.notification small{opacity:.65}.notification button{border:0;background:none;cursor:pointer}.notification-timer{position:absolute;bottom:0;left:0;height:2px;width:100%;animation:noticeTimer 7s linear forwards;transform-origin:left}.notification-timer.paused{animation-play-state:paused}@keyframes noticeTimer{from{transform:scaleX(1)}to{transform:scaleX(0)}}@media(max-width:800px){.resource-metric-grid,.resource-chart-grid{grid-template-columns:1fr 1fr}}\n''')

Path('tests/test_monitoring.py').write_text('''import tempfile\nimport unittest\nfrom src.domains.monitoring.service import ResourceMonitor\n\nclass ResourceMonitorTests(unittest.TestCase):\n    def test_snapshot_has_core_metrics(self):\n        with tempfile.TemporaryDirectory() as root:\n            data = ResourceMonitor(30).snapshot(root)\n            self.assertIn("cpu_percent", data)\n            self.assertIn("ram_percent", data)\n            self.assertIn("process_rss_bytes", data)\n            self.assertIn("disk_free_bytes", data)\n\n    def test_history_is_bounded(self):\n        with tempfile.TemporaryDirectory() as root:\n            monitor = ResourceMonitor(30)\n            for _ in range(50):\n                monitor.snapshot(root)\n            self.assertLessEqual(len(monitor.history), 30)\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding='utf-8')

